import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String s = reader.readLine();
        if (s == null || s.trim().isEmpty()) {
            return;
        }
        s = s.trim();

        boolean[][] seen = new boolean[4][14];
        boolean[] duplicate = new boolean[4];
        int[] count = new int[4];

        for (int i = 0; i < s.length(); i += 3) {
            int val = (s.charAt(i) - '0') * 10 + (s.charAt(i + 1) - '0');
            char suitChar = s.charAt(i + 2);

            int suitIndex = -1;
            switch (suitChar) {
                case 'C': suitIndex = 0; break;
                case 'E': suitIndex = 1; break;
                case 'U': suitIndex = 2; break;
                case 'P': suitIndex = 3; break;
            }

            if (seen[suitIndex][val]) {
                duplicate[suitIndex] = true;
            } else {
                seen[suitIndex][val] = true;
                count[suitIndex]++;
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 4; i++) {
            if (duplicate[i]) {
                sb.append("erro\n");
            } else {
                sb.append(13 - count[i]).append("\n");
            }
        }

        System.out.print(sb);
    }
}
